  "name": "POReviewFlow",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "d236c7be-1b6e-42ab-bed2-5e6f00c13afd",
