    {
      "id": "poReview",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "PO Review"
      },
      "inputs": {
        "title": "Purchase Order Review",
        "priority": "High",
        "schema": {
          "schemaId": "c7e3a1f2-84b9-4d56-9e0a-3f72b8c50d91",
          "fields": [
            {
              "id": "poNumber",
              "label": "PO Number",
              "type": "text",
              "direction": "input",
              "binding": "vars.start.output.poNumber"
            },
            {
              "id": "vendorName",
              "label": "Vendor Name",
              "type": "text",
              "direction": "input",
              "binding": "vars.start.output.vendorName"
            },
            {
              "id": "totalAmount",
              "label": "Total Amount",
              "type": "number",
              "direction": "input",
              "binding": "vars.start.output.totalAmount"
            },
            {
              "id": "notes",
              "label": "Notes (optional)",
              "type": "text",
              "direction": "output",
              "variable": "vars.notes"
            }
          ],
          "outcomes": [
            {
              "id": "approve",
              "name": "Approve",
              "type": "string",
              "isPrimary": true,
              "action": "Continue"
            },
            {
              "id": "reject",
              "name": "Reject",
              "type": "string",
              "isPrimary": false,
              "action": "End"
            }
          ]
        },
        "recipient": {
          "channels": [
            "Email",
            "ActionCenter"
          ],
          "connections": {},
          "assignee": {
            "type": "group"
          }
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "notes": {
              "type": "string"
            },
            "Action": {
              "type": "string",
              "enum": [
                "Approve",
                "Reject"
              ],
              "default": "Approve"
            }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": [
            "Approve",
            "Reject"
          ],
          "default": "Approve"
        }
      }
    },
    {
      "id": "checkApproval",
      "type": "core.logic.decision",
      "typeVersion": "1.2",
      "display": {
        "label": "Approved?"
      },
      "inputs": {
        "expression": "$vars.poReview.status === \"Approve\"",
        "trueLabel": "Approved",
        "falseLabel": "Rejected"
      }
    },
    {
      "id": "logApproval",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "display": {
        "label": "Log Approval"
      },
      "inputs": {
        "script": "return { message: \"PO approved.\" };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "endApproved",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Done"
      },
      "inputs": {}
    },
    {
      "id": "endRejected",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Rejected"
      },
      "inputs": {}
    }
  ],
  "edges": [
    {
      "id": "e-start-poReview",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "poReview",
      "targetPort": "input"
    },
    {
      "id": "e-poReview-checkApproval",
      "sourceNodeId": "poReview",
      "sourcePort": "completed",
      "targetNodeId": "checkApproval",
      "targetPort": "input"
    },
    {
      "id": "e-checkApproval-logApproval",
      "sourceNodeId": "checkApproval",
      "sourcePort": "true",
      "targetNodeId": "logApproval",
      "targetPort": "input"
    },
    {
      "id": "e-checkApproval-endRejected",
      "sourceNodeId": "checkApproval",
      "sourcePort": "false",
      "targetNodeId": "endRejected",
      "targetPort": "input"
    },
    {
      "id": "e-logApproval-endApproved",
      "sourceNodeId": "logApproval",
      "sourcePort": "success",
      "targetNodeId": "endApproved",
      "targetPort": "input"
    }
  ],
  "definitions": [
    {
      "nodeType": "core.trigger.manual",
      "version": "1.0",
      "category": "trigger",
      "description": "Start the process manually",
      "tags": [
        "trigger",
        "start",
        "manual"
      ],
      "sortOrder": 80,
      "display": {
        "label": "Manual trigger",
        "icon": "play",
        "shape": "circle"
      },
      "handleConfiguration": [
        {
          "position": "right",
          "handles": [
            {
              "id": "output",
              "type": "source",
              "handleType": "output",
